<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Receipt {{ $payment->id }}</title>
<style>body{margin:0;background:#f3f5f8;color:#182230;font:15px/1.5 Arial,sans-serif}.sheet{max-width:680px;margin:32px auto;background:#fff;padding:40px;border:1px solid #e5e7eb}.brand{font-size:22px;font-weight:700;color:#172b4d}.muted{color:#667085}.line{display:flex;justify-content:space-between;gap:18px;padding:12px 0;border-bottom:1px solid #e5e7eb}.amount{font-size:28px;font-weight:700}.actions{max-width:680px;margin:0 auto 30px;text-align:right}.actions button{background:#172b4d;color:white;border:0;border-radius:8px;padding:11px 18px;cursor:pointer}@media print{body{background:#fff}.sheet{margin:0 auto;border:0;padding:20px}.actions{display:none}@page{size:A4;margin:18mm}}@media(max-width:600px){.sheet{margin:0;padding:22px}}</style></head>
<body><div class="actions"><button onclick="window.print()">Print / Save as PDF</button></div><main class="sheet"><div class="brand">Alom’s English Center</div><div class="muted">Official payment receipt</div><h1>PAYMENT RECEIPT</h1><div class="line"><span>Receipt ID</span><strong>RCPT-{{ str_pad((string)$payment->id,8,'0',STR_PAD_LEFT) }}</strong></div><div class="line"><span>Invoice</span><strong>{{ $invoice->invoice_number }}</strong></div><div class="line"><span>Student</span><strong>{{ $invoice->user->name }}</strong></div><div class="line"><span>Invoice title</span><strong>{{ $invoice->title }}</strong></div><div class="line"><span>Payment date</span><strong>{{ $payment->paid_at?->format('d M Y H:i') }}</strong></div><div class="line"><span>Payment method</span><strong>{{ $payment->method }}</strong></div><div class="line"><span>Transaction reference</span><strong>{{ $payment->reference ?: '—' }}</strong></div><div class="line amount"><span>Amount received</span><strong>৳{{ number_format((float)$payment->amount,2) }}</strong></div><div class="line"><span>Received by</span><strong>{{ $payment->receiver?->name ?? 'Alom’s English Center' }}</strong></div><p class="muted" style="margin-top:32px;text-align:center">Thank you. This receipt is computer generated.</p></main></body></html>
